FUNCTION_BLOCK LED_Control
VAR_INPUT
    PB1 : BOOL;
    PB2 : BOOL;
END_VAR
VAR_OUTPUT
    LED : BOOL;
END_VAR

VAR
    PB2_Not : BOOL;
END_VAR

// Calculate the negation of PB2
PB2_Not := NOT PB2;

// Perform the logical AND operation between PB1 and the negation of PB2
LED := PB1 AND PB2_Not;

END_FUNCTION_BLOCK
